function PlotOrderedCoef(wc)% PlotOrderCoef -- Plot Ordered Coefficients%  Usage%    PlotOrderedCoef(wc)%  Inputs%    wc     wavelet coeffs%	[n,J] = dyadlength(wc);	ordcoef = reverse(sort(abs(wc)));%	semilogy(1:n,ordcoef)	        %   % Part of WaveLab Version 802% Built Sunday, October 3, 1999 8:52:27 AM% This is Copyrighted Material% For Copying permissions see COPYING.m% Comments? e-mail wavelab@stat.stanford.edu%       